const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const country = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Afghanistan'))
      .geometry();

    const feb2017Start = ee.Date.fromYMD(2017, 2, 1);
    const feb2017End = feb2017Start.advance(1, 'month');
    const feb2018Start = ee.Date.fromYMD(2018, 2, 1);
    const feb2018End = feb2018Start.advance(1, 'month');

    const scale = 3000;

    // 2. Masking and LST conversion
    function lstMaskC(img) {
      const qc = img.select('QC_Day');
      const good = qc.bitwiseAnd(3).eq(0); // bits 0-1 == 00 => good quality
      const lstC = img.select('LST_Day_1km')
        .updateMask(good)
        .multiply(0.02)
        .subtract(273.15)
        .rename('LST_C');
      return lstC.copyProperties(img, img.propertyNames());
    }

    async function monthComposite(year, start, end) {
      const terraId = 'MODIS/061/MOD11A2';
      const aquaId = 'MODIS/061/MYD11A2';

      const colTerra = ee.ImageCollection(terraId).filterDate(start, end).filterBounds(country).map(lstMaskC);
      const terraSize = await colTerra.size().getInfo();

      let col = colTerra;
      let datasetUsed = 'MOD11A2 (Terra)';
      if (!terraSize || terraSize === 0) {
        const colAqua = ee.ImageCollection(aquaId).filterDate(start, end).filterBounds(country).map(lstMaskC);
        const aquaSize = await colAqua.size().getInfo();
        if (!aquaSize || aquaSize === 0) {
          return { year, imgs: 0, dataset: 'None', img: null };
        }
        col = colAqua;
        datasetUsed = 'MYD11A2 (Aqua)';
      }
      const imgs = await col.size().getInfo();
      const img = col.mean();
      return { year, imgs, dataset: datasetUsed, img };
    }

    const m2017 = await monthComposite(2017, feb2017Start, feb2017End);
    const m2018 = await monthComposite(2018, feb2018Start, feb2018End);

    if (!m2017.img || !m2018.img) {
      console.log(`2017 Feb Images: ${m2017.imgs}`);
      console.log(`2018 Feb Images: ${m2018.imgs}`);
      console.log('Empty ImageCollection in one or both months.');
      console.log('C1');
      return;
    }

    // 3. Pixel counts and means
    async function statsFor(imgObj) {
      const validCount = await imgObj.img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: country,
        scale: scale,
        maxPixels: 1e9
      }).get('LST_C').getInfo();

      const totalCount = await ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: country,
        scale: scale,
        maxPixels: 1e9
      }).get('ones').getInfo();

      const meanVal = await imgObj.img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: country,
        scale: scale,
        maxPixels: 1e9
      }).get('LST_C').getInfo();

      return { validCount: validCount || 0, totalCount: totalCount || 0, mean: meanVal };
    }

    const s2017 = await statsFor(m2017);
    const s2018 = await statsFor(m2018);

    console.log(`2017 Feb - ${m2017.dataset} imgs: ${m2017.imgs}`);
    console.log(`2018 Feb - ${m2018.dataset} imgs: ${m2018.imgs}`);

    if ((s2017.validCount === 0) || (s2018.validCount === 0)) {
      console.log(`2017 Valid px: ${s2017.validCount}/${s2017.totalCount}`);
      console.log(`2018 Valid px: ${s2018.validCount}/${s2018.totalCount}`);
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // Validate mean values
    function invalidMean(v) {
      return v === null || v === undefined || !isFinite(v) || v < -100 || v > 100;
    }
    if (invalidMean(s2017.mean) || invalidMean(s2018.mean)) {
      console.log(`2017 Mean LST_C: ${s2017.mean}`);
      console.log(`2018 Mean LST_C: ${s2018.mean}`);
      console.log('Calculation failure (null/NaN/unrealistic).');
      console.log('C3');
      return;
    }

    const vPerc2017 = s2017.totalCount ? (100.0 * s2017.validCount / s2017.totalCount) : 0;
    const vPerc2018 = s2018.totalCount ? (100.0 * s2018.validCount / s2018.totalCount) : 0;

    console.log(`2017 Valid px: ${s2017.validCount}/${s2017.totalCount} (${vPerc2017.toFixed(1)}%) ; Mean LST_C: ${s2017.mean.toFixed(2)}°C`);
    console.log(`2018 Valid px: ${s2018.validCount}/${s2018.totalCount} (${vPerc2018.toFixed(1)}%) ; Mean LST_C: ${s2018.mean.toFixed(2)}°C`);

    const diff = s2018.mean - s2017.mean;
    console.log(`Difference (2018-2017): ${diff.toFixed(2)}°C`);

    // 5. Final Answer
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
